// ============================================================
//  Ballpit.jsx — FINAL FIXED & OPTIMIZED
// ============================================================

import { useEffect, useRef } from 'react';
import * as THREE from 'three';

const Ballpit = ({
  count = 60,
  gravity = 0.085,
  friction = 0.982,
  wallBounce = 0.91,
}) => {
  const canvasRef = useRef(null);
  const rafRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    // Scene Setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.z = 22;

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true,
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Lights
    scene.add(new THREE.AmbientLight(0xffffff, 0.7));
    const pointLight = new THREE.PointLight(0x818cf8, 2.8, 100);
    scene.add(pointLight);

    // Balls
    const geometry = new THREE.SphereGeometry(1, 32, 32);
    const material = new THREE.MeshPhysicalMaterial({
      color: 0x6366f1,
      metalness: 0.7,
      roughness: 0.25,
      clearcoat: 1,
      clearcoatRoughness: 0.1,
    });

    const balls = new THREE.InstancedMesh(geometry, material, count);
    const dummy = new THREE.Object3D();
    scene.add(balls);

    // Physics Data
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    const sizes = new Float32Array(count);

    // Initialize balls
    for (let i = 0; i < count; i++) {
      const idx = i * 3;
      positions[idx]     = (Math.random() - 0.5) * 20;
      positions[idx + 1] = (Math.random() - 0.5) * 15;
      positions[idx + 2] = (Math.random() - 0.5) * 10;

      velocities[idx]     = (Math.random() - 0.5) * 2;
      velocities[idx + 1] = (Math.random() - 0.5) * 2;
      velocities[idx + 2] = (Math.random() - 0.5) * 1.5;

      sizes[i] = 0.6 + Math.random() * 0.9;
    }

    let lastTime = 0;

    const animate = (time = 0) => {
      rafRef.current = requestAnimationFrame(animate);
      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      // Update Physics
      for (let i = 0; i < count; i++) {
        const idx = i * 3;

        velocities[idx + 1] -= gravity * delta * 55;

        velocities[idx] *= friction;
        velocities[idx + 1] *= friction;
        velocities[idx + 2] *= friction;

        positions[idx]     += velocities[idx] * delta * 55;
        positions[idx + 1] += velocities[idx + 1] * delta * 55;
        positions[idx + 2] += velocities[idx + 2] * delta * 55;

        const radius = sizes[i];

        if (Math.abs(positions[idx]) + radius > 13) {
          positions[idx] = Math.sign(positions[idx]) * (13 - radius);
          velocities[idx] *= -wallBounce;
        }
        if (positions[idx + 1] - radius < -9) {
          positions[idx + 1] = -9 + radius;
          velocities[idx + 1] *= -wallBounce;
        }
        if (Math.abs(positions[idx + 2]) + radius > 6) {
          positions[idx + 2] = Math.sign(positions[idx + 2]) * (6 - radius);
          velocities[idx + 2] *= -wallBounce;
        }
      }

      // Update Instanced Mesh
      for (let i = 0; i < count; i++) {
        const idx = i * 3;
        dummy.position.set(positions[idx], positions[idx + 1], positions[idx + 2]);
        dummy.scale.setScalar(sizes[i]);
        dummy.updateMatrix();
        balls.setMatrixAt(i, dummy.matrix);
      }

      pointLight.position.set(positions[0], positions[1] + 2, positions[2] + 4);

      balls.instanceMatrix.needsUpdate = true;
      renderer.render(scene, camera);
    };

    // Handle Resize
    const handleResize = () => {
      camera.aspect = canvas.parentElement.offsetWidth / canvas.parentElement.offsetHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(canvas.parentElement.offsetWidth, canvas.parentElement.offsetHeight);
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    animate();

    // Cleanup
    return () => {
      cancelAnimationFrame(rafRef.current);
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [count, gravity, friction, wallBounce]);

  return (
    <canvas
      ref={canvasRef}
      className="hero__ballpit"
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Ballpit;
